-- Epic #441 (alexkulya audit rows WU005); staged 2026-09-23,
-- re-checked 2026-10-04 against the LoA base world dump + sql/updates and LoA SmartAI enums.
-- LoA port: Venom Web Spider (entry 217, Duskwood) - Cataclysm-era SmartAI (self-buff Pygmy 85246) replacing LoA's
-- classic Web 745 / Poison 744 rows, and spawn cleanup (LoA had 76 spawns incl. 12 on short waypoint paths -> 46 spawns).
-- Source: alexkulya ref commit fcc47a7, sql/updates/world/2026_08_23_00_world_venom_web_spider.sql.
-- Adaptations for LoA:
--  * creature.movement_type -> creature.MovementType. smart_scripts: LoA-only columns event_param5/target_param4 take default 0.
--  * guids verified: all 76 LoA spawns of 217 have the same guid+position as ak_world; every inserted guid was a 217 spawn;
--    DELETE guarded by `id` = 217; no formation/pool/game_event/linked_respawn references.
-- Re-runnable: addon/waypoint/smart_scripts/creature rows are deleted before being inserted.

DELETE FROM `creature_addon` WHERE `guid` IN (SELECT `guid` FROM `creature` WHERE `id` = 217);
DELETE FROM `waypoint_data` WHERE `id` IN (SELECT `guid` FROM `creature` WHERE `id` = 217);
DELETE FROM `creature_template_addon` WHERE `entry` = 217;

UPDATE `creature_template` SET `unit_flags` = 0 WHERE `entry` = 217;

DELETE FROM `smart_scripts` WHERE `entryorguid` = 217 AND `source_type` = 0;

DELETE FROM `creature` WHERE `guid` IN (170445, 170575, 170577, 170578, 170579, 170583, 170584, 170597, 170598, 170625, 170636, 170650, 170651, 170653,
